import{_ as e,c as o,o as t,ag as a}from"./chunks/framework.ko2zIC2c.js";const f=JSON.parse('{"title":"Vilinko Studio Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"en/agreement/privacy.md","filePath":"en/agreement/privacy.md"}'),r={name:"en/agreement/privacy.md"};function n(s,i,l,c,u,d){return t(),o("div",null,i[0]||(i[0]=[a('<h1 id="vilinko-studio-privacy-policy" tabindex="-1">Vilinko Studio Privacy Policy <a class="header-anchor" href="#vilinko-studio-privacy-policy" aria-label="Permalink to &quot;Vilinko Studio Privacy Policy&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Version</p><p>Initial release date: August 6, 2025</p><p>Last updated date: August 6, 2025</p></div><p>In case of any conflict, the <a href="/agreement/privacy.html"><strong>Simplified Chinese version</strong></a> shall prevail.</p><h2 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1. Introduction&quot;">​</a></h2><ul><li>Welcome to use the internet information technology tools and related services provided by Vilinko Studio (hereinafter referred to as &quot;we&quot;). This Privacy Policy aims to explain to you how we collect, use, store, protect and disclose your personal information, as well as the rights you enjoy related to personal information.</li><li>This Privacy Policy is closely related to your use of our services. Please carefully read and fully understand this Policy before using any service, especially the content marked in bold or underlined. Your use or continued use of our services means that you agree to our processing of your personal information in accordance with this Policy.</li><li>If you have any questions about this Policy, you can contact us through the methods provided in this Policy.</li></ul><h2 id="_2-scope-of-application" tabindex="-1">2. Scope of Application <a class="header-anchor" href="#_2-scope-of-application" aria-label="Permalink to &quot;2. Scope of Application&quot;">​</a></h2><ul><li>This Policy applies to all services provided by us, including but not limited to user login systems, forum services, personalized customization functions, computer desktop beautification tools, file interpreters, as well as related websites, clients, mini-programs, etc.</li><li>This Policy does not apply to the following situations: <ul><li>Products or services provided to you by third parties through our services. Such third-party services may have their own independent privacy policies, and we are not responsible for third parties&#39; privacy policies and behaviors.</li><li>Third-party services authorized by us, but such authorization does not include authorization for third parties to collect and use your personal information. Third parties shall process your information in accordance with their own privacy policies.</li></ul></li></ul><h2 id="_3-information-we-collect" tabindex="-1">3. Information We Collect <a class="header-anchor" href="#_3-information-we-collect" aria-label="Permalink to &quot;3. Information We Collect&quot;">​</a></h2><h3 id="_1-information-you-voluntarily-provide" tabindex="-1">(1) Information You Voluntarily Provide <a class="header-anchor" href="#_1-information-you-voluntarily-provide" aria-label="Permalink to &quot;(1) Information You Voluntarily Provide&quot;">​</a></h3><ul><li>Registration information: When you register a Vilinko Studio account, you may need to provide a mobile phone number, email address, username, password and other information. If you choose to log in through a third-party account (such as WeChat, QQ, GitHub, etc.), we will obtain the information you have made public on the third-party platform (such as nickname, avatar, etc.), which is subject to the content displayed on the third-party authorization page.</li><li>Information submitted during service usage: <ul><li>Content such as posts, comments, replies, private messages you publish when using the forum service.</li><li>Pictures you upload, preference parameters you set, text descriptions you input when using the personalized customization function.</li><li>Opinions, suggestions, complaints and relevant supporting materials you submit to us through the customer service system and feedback channels.</li></ul></li><li>Other voluntarily provided information: Such as name, address, contact information you provide when participating in our questionnaires and activities.</li></ul><h3 id="_2-information-we-collect-during-your-use-of-services" tabindex="-1">(2) Information We Collect During Your Use of Services <a class="header-anchor" href="#_2-information-we-collect-during-your-use-of-services" aria-label="Permalink to &quot;(2) Information We Collect During Your Use of Services&quot;">​</a></h3><ul><li>Device information: Including device model, operating system type and version, device identifiers (such as IMEI, MEID, Android ID, IDFA, MAC address, etc.), device hardware information (such as CPU, memory, storage capacity), battery status, sensor information (such as acceleration sensor, gyroscope), etc.</li><li>Network information: Including IP address, network type (such as Wi-Fi, 4G, 5G), network operator, access point name (APN), Bluetooth information, Wi-Fi hotspot information, etc.</li><li>Location information: <ul><li>If you agree to use functions involving location services (such as location-based resource recommendations) and authorize us to obtain location information, we may obtain your precise location information through GPS, base stations, Wi-Fi, etc.</li><li>If you do not authorize, but the service function requires approximate location information, we may obtain your approximate geographical location based on your IP address and other information.</li><li>You can turn off the location information authorization through the device system settings or the permission management function in the service at any time. After turning off, we will no longer collect it, but it may affect the normal use of related functions.</li></ul></li><li>Log information: <ul><li>Access logs: Including the time, location, pages or functions you access, duration of access, click records, etc.</li><li>Operation logs: Including your operation behaviors in the service (such as login, logout, modification of settings, file upload, resource download, etc.), operation results, error information, etc.</li><li>Device operation logs: Including the running status, crash information, exception logs of the service on your device, which are used to troubleshoot faults and optimize performance.</li></ul></li><li>File information: <ul><li>When you use the file interpreter function, we will temporarily read the content of the file to be interpreted that you select, which is only used to complete the interpretation operation. After the operation is completed, the temporary data will be cleared according to the settings (unless you choose to save the result).</li><li>Files you upload and store through the service (such as personalized beautification materials, forum attachments, etc.) will be stored and managed by us according to your settings.</li></ul></li></ul><h3 id="_3-information-obtained-from-third-parties" tabindex="-1">(3) Information Obtained from Third Parties <a class="header-anchor" href="#_3-information-obtained-from-third-parties" aria-label="Permalink to &quot;(3) Information Obtained from Third Parties&quot;">​</a></h3><ul><li>If you use our services through a third-party cooperation platform or authorize a third party to provide us with your information, we will obtain relevant information about you on the third-party platform under the premise of complying with laws and regulations and mutual agreements, which is subject to your agreement with the third party and the scope of authorization.</li><li>To ensure service security and prevent fraud risks, we may obtain risk assessment information about you from legally compliant third-party institutions.</li></ul><h2 id="_4-how-we-use-information" tabindex="-1">4. How We Use Information <a class="header-anchor" href="#_4-how-we-use-information" aria-label="Permalink to &quot;4. How We Use Information&quot;">​</a></h2><ul><li>Provide you with services: Create an account for you based on your registration information to ensure your normal use of various service functions; process relevant requests based on your operation instructions (such as interpreting files, publishing forum content).</li><li>Optimize service experience: <ul><li>Optimize the compatibility and stability of the service on different devices according to device information and operation logs, and fix vulnerabilities and faults.</li></ul></li><li>Ensure service security: <ul><li>Use device information, network information, log information, etc. to identify risks such as abnormal login and malicious attacks, and take security measures to protect your account and information security.</li><li>Monitor and handle behaviors that violate laws, regulations or service agreements to maintain service order.</li></ul></li><li>Communication and notification: <ul><li>Send you service-related notifications (such as account registration success notification, password reset reminder, service update announcement, etc.).</li><li>With your consent, push activity information and other content to you, which you can cancel receiving through relevant settings.</li></ul></li><li>Legal requirements or protection of legitimate rights and interests: <ul><li>Use your information to comply with laws and regulations and respond to legal requirements from judicial or administrative authorities.</li><li>Use your information within a reasonable and necessary scope to safeguard the legitimate rights and interests of us and users (such as responding to lawsuits, arbitrations).</li></ul></li><li>Other purposes with your consent: Such as for market research, product improvement, etc., we will clearly inform you and obtain your consent before use.</li></ul><h2 id="_5-storage-and-protection-of-information" tabindex="-1">5. Storage and Protection of Information <a class="header-anchor" href="#_5-storage-and-protection-of-information" aria-label="Permalink to &quot;5. Storage and Protection of Information&quot;">​</a></h2><h3 id="_1-storage-location" tabindex="-1">(1) Storage Location <a class="header-anchor" href="#_1-storage-location" aria-label="Permalink to &quot;(1) Storage Location&quot;">​</a></h3><ul><li>Your personal information is stored on servers within the territory of the People&#39;s Republic of China.</li></ul><h3 id="_2-storage-period" tabindex="-1">(2) Storage Period <a class="header-anchor" href="#_2-storage-period" aria-label="Permalink to &quot;(2) Storage Period&quot;">​</a></h3><ul><li>We will determine a reasonable storage period according to the type of information and the purpose of use: <ul><li>Account information: We will continue to store it while your account is active; if you cancel your account, we will delete or anonymize it within a reasonable period.</li><li>If otherwise specified by laws and regulations, such provisions shall apply (for example, the storage period of information that needs to be retained for performing statutory duties or dealing with disputes may be extended).</li></ul></li></ul><h3 id="_3-protection-measures" tabindex="-1">(3) Protection Measures <a class="header-anchor" href="#_3-protection-measures" aria-label="Permalink to &quot;(3) Protection Measures&quot;">​</a></h3><ul><li>Adopt technical means such as encryption technology (such as SSL/TLS encrypted transmission, encrypted data storage), access control mechanisms, firewalls, intrusion detection systems to prevent information from being accessed, leaked, tampered with or damaged without authorization.</li><li>Formulate emergency plans for data security incidents. In case of security incidents such as information leakage, we will take timely remedial measures and report to relevant departments and notify you in accordance with regulations.</li></ul><h2 id="_6-sharing-transfer-and-public-disclosure-of-information" tabindex="-1">6. Sharing, Transfer and Public Disclosure of Information <a class="header-anchor" href="#_6-sharing-transfer-and-public-disclosure-of-information" aria-label="Permalink to &quot;6. Sharing, Transfer and Public Disclosure of Information&quot;">​</a></h2><h3 id="_1-sharing" tabindex="-1">(1) Sharing <a class="header-anchor" href="#_1-sharing" aria-label="Permalink to &quot;(1) Sharing&quot;">​</a></h3><ul><li>We will not share your personal information with third parties unless the following conditions are met: <ul><li>Obtain your explicit consent: Before sharing, we will clearly inform you of the purpose of sharing, the identity of the third party and the scope of information, and share it after your confirmation and consent.</li><li>Service necessity: To provide you with services, it is necessary to share necessary information with third-party service providers (such as server hosting providers, cloud storage service providers, payment service providers, etc.). Such third parties can only use the information within the scope of providing services and must abide by confidentiality obligations.</li><li>Legal requirements: Share information with relevant departments in accordance with laws and regulations, or mandatory requirements from judicial or administrative authorities.</li><li>Protection of legitimate rights and interests: Share information with relevant parties within a reasonable and necessary scope to protect the legitimate rights and interests of us and users (such as preventing fraud, handling infringement behaviors).</li></ul></li></ul><h3 id="_2-transfer" tabindex="-1">(2) Transfer <a class="header-anchor" href="#_2-transfer" aria-label="Permalink to &quot;(2) Transfer&quot;">​</a></h3><ul><li>Without your explicit consent, we will not transfer your personal information to any third party. If it needs to be transferred due to enterprise merger, division, acquisition, reorganization, etc., we will notify you in advance and ensure that the transferee continues to comply with the provisions of this Policy; if you disagree, you can choose to cancel your account.</li></ul><h3 id="_3-public-disclosure" tabindex="-1">(3) Public Disclosure <a class="header-anchor" href="#_3-public-disclosure" aria-label="Permalink to &quot;(3) Public Disclosure&quot;">​</a></h3><ul><li>We will not publicly disclose your personal information unless the following conditions are met: <ul><li>Obtain your explicit consent.</li><li>Required by laws and regulations or instructed by competent authorities.</li><li>Disclose publicly within a necessary scope to maintain public interests (such as combating crimes).</li><li>Information you actively disclose in the service (such as public forum posts), and the scope of public disclosure of such information is subject to your settings.</li></ul></li></ul><h2 id="_7-your-rights" tabindex="-1">7. Your Rights <a class="header-anchor" href="#_7-your-rights" aria-label="Permalink to &quot;7. Your Rights&quot;">​</a></h2><ul><li>Right of access: You have the right to access your personal information (such as basic account information, usage records, etc.).</li><li>Right of correction: If you find errors in your information, you can apply to us for correction, and we will correct it in a timely manner after verification.</li><li>Right of deletion: You can request us to delete your personal information in the following cases: <ul><li>The purpose of our collection and use of information has been achieved or is no longer necessary.</li><li>You withdraw your consent authorization.</li><li>We process your information in violation of laws, regulations or agreement.</li><li>Other situations where deletion is legally required.</li><li>We will delete it in a timely manner after verification. If it needs to be retained due to legal regulations, we will anonymize it.</li></ul></li><li>Right to withdraw consent: You can withdraw your authorization for us to collect and use information at any time (such as turning off permission settings), but withdrawing consent may cause some service functions to be unavailable.</li><li>Right of duplication: You can request us to provide a copy of your personal information, and we will provide it in a reasonable way under the prescribed premise.</li><li>Right of cancellation: You can cancel your account through the cancellation function in the service or by contacting customer service. After cancellation, we will stop providing services for you and process your information (delete or anonymize) in accordance with regulations.</li><li>Right to restrict automated decision-making: For decisions made through automated decision-making methods (such as algorithm recommendations) that have a significant impact on your rights and interests, you have the right to request us to explain and can refuse to process your information only through automated decision-making.</li></ul><h2 id="_8-protection-of-minors" tabindex="-1">8. Protection of Minors <a class="header-anchor" href="#_8-protection-of-minors" aria-label="Permalink to &quot;8. Protection of Minors&quot;">​</a></h2><ul><li>We attach great importance to the protection of minors&#39; personal information. If you are a minor under the age of 18, you should use our services under the guidance of a guardian and the guardian should read this Policy on your behalf.</li><li>The guardian of a minor should properly manage the minor&#39;s account and personal information. If it is found that the minor&#39;s information is improperly collected or used, you can contact us for handling.</li><li>We will not provide minors with service content inappropriate for their age, nor will we disclose minors&#39; personal information to third parties without the guardian&#39;s consent.</li></ul><h2 id="_9-update-and-notification-of-the-policy" tabindex="-1">9. Update and Notification of the Policy <a class="header-anchor" href="#_9-update-and-notification-of-the-policy" aria-label="Permalink to &quot;9. Update and Notification of the Policy&quot;">​</a></h2><ul><li>We may revise this Privacy Policy according to changes in laws and regulations, adjustments to service functions, etc.</li><li>The revised Privacy Policy will be announced in prominent positions such as our official website and service client, and the effective date will be indicated. If the revised content involves significant changes to your rights and interests, we will prompt you through pop-ups, text messages, emails, etc., and give you a reasonable consideration period.</li><li>Your continued use of our services means that you agree to the revised Privacy Policy; if you disagree, you should stop using the services.</li></ul><h2 id="_10-contact-us" tabindex="-1">10. Contact Us <a class="header-anchor" href="#_10-contact-us" aria-label="Permalink to &quot;10. Contact Us&quot;">​</a></h2><ul><li>If you have any questions, suggestions or complaints about this Privacy Policy, you can contact us through the following methods: <ul><li>Email: <a href="mailto:privacy@vilinko.com" target="_blank" rel="noreferrer">privacy@vilinko.com</a></li><li>Create a ticket: <a href="https://vilinko-studio.feishu.cn/share/base/form/shrcnMi5t1NY40A0fjdTN2oRO5e" target="_blank" rel="noreferrer">Vilinko Studio Ticket Creation Assistant</a></li></ul></li><li>We will verify and reply within 15 working days after receiving your feedback.</li></ul><h2 id="appendix-links-to-third-party-policies" tabindex="-1">Appendix: Links to Third-Party Policies <a class="header-anchor" href="#appendix-links-to-third-party-policies" aria-label="Permalink to &quot;Appendix: Links to Third-Party Policies&quot;">​</a></h2><ul><li><a href="https://afdian.com/term" target="_blank" rel="noreferrer">Afadian Platform Service Terms</a></li></ul>',40)]))}const m=e(r,[["render",n]]);export{f as __pageData,m as default};
